# Restore the file to a clean state
git restore src/de/gurkenlabs/litiengine/resources/ResourceBundle.java && \
# Insert Objects import after existing java.util imports
sed -i '/import java.util.Collections;/a import java.util.Objects;' src/de/gurkenlabs/litiengine/resources/ResourceBundle.java && \
# Rewrite the beforeMarshal method with a here-doc to ensure it is clean and uses Objects.equals
python - << 'EOF'
from pathlib import Path

path = Path("src/de/gurkenlabs/litiengine/resources/ResourceBundle.java")
text = path.read_text()

old = """  void beforeMarshal(Marshaller m) {
    List<SpritesheetResource> distinctList = new ArrayList<>();
    for (SpritesheetResource sprite : this.getSpriteSheets()) {
      if (distinctList.stream()
          .anyMatch(
              x ->
                  x.getName().equals(sprite.getName()) && x.getImage().equals(sprite.getImage()))) {
        continue;
      }

      distinctList.add(sprite);
    }

    this.spriteSheets = distinctList;

    List<Tileset> distinctTilesets = new ArrayList<>();
    for (Tileset tileset : this.getTilesets()) {
      if (distinctTilesets.stream().anyMatch(x -> x.getName().equals(tileset.getName()))) {
        continue;
      }

      distinctTilesets.add(tileset);
    }

    this.tilesets = distinctTilesets;

    if (this.version == 0) {
      this.version = CURRENT_VERSION;
    }
  }
"""

new = """  void beforeMarshal(Marshaller m) {
    List<SpritesheetResource> distinctList = new ArrayList<>();
    for (SpritesheetResource sprite : this.getSpriteSheets()) {
      if (distinctList.stream()
          .anyMatch(
              x ->
                  Objects.equals(x.getName(), sprite.getName())
                      && Objects.equals(x.getImage(), sprite.getImage())))) {
        continue;
      }

      distinctList.add(sprite);
    }

    this.spriteSheets = distinctList;

    List<Tileset> distinctTilesets = new ArrayList<>();
    for (Tileset tileset : this.getTilesets()) {
      if (distinctTilesets.stream().anyMatch(x -> x.getName().equals(tileset.getName()))) {
        continue;
      }

      distinctTilesets.add(tileset);
    }

    this.tilesets = distinctTilesets;

    if (this.version == 0) {
      this.version = CURRENT_VERSION;
    }
  }
"""

if old not in text:
    raise SystemExit("Expected original beforeMarshal block not found; aborting to avoid corruption.")
path.write_text(text.replace(old, new))
EOF
```

